SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, u.avatar as teacher_avatar, c.assistant_teacher_ids, c.cover_image_url, c.status, c.is_public, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id LEFT JOIN sys_user u ON t.sys_user_id = u.id
c.is_deleted = 0 AND t.is_deleted = 0
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.teacher_id = #{teacherId}
AND c.status = #{status}
AND c.is_public = #{isPublic}
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
AND c.create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY c.create_time DESC

SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, u.avatar as teacher_avatar, c.assistant_teacher_ids, c.cover_image_url, c.status, c.is_public, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id LEFT JOIN sys_user u ON t.sys_user_id = u.id
c.is_deleted = 0 AND t.is_deleted = 0
AND c.teacher_id = #{teacherId}
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.status = #{status}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY c.create_time DESC

SELECT c.id, c.course_name, c.description, c.cover_image_url, c.course_type, c.semester, c.location, t.real_name as teacher_name, u.avatar as teacher_avatar, c.is_public, c.create_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id LEFT JOIN sys_user u ON t.sys_user_id = u.id
c.is_deleted = 0 AND (t.is_deleted = 0 OR t.id IS NULL) AND c.status = 0 AND c.is_public = #{isPublic}
ORDER BY RAND() LIMIT 8
